static D2D1_COLOR_F color(unsigned rgb,float alpha=1){return D2D1::ColorF(float(rgb>>16)/255,float((rgb>>8)&255)/255,float(rgb&255)/255,alpha);}
static D2D1_COLOR_F blend(D2D1_COLOR_F a,D2D1_COLOR_F b,float t){return {std::lerp(a.r,b.r,t),std::lerp(a.g,b.g,t),std::lerp(a.b,b.b,t),std::lerp(a.a,b.a,t)};}
static bool contains(D2D1_RECT_F rect,float x,float y){return x>=rect.left&&x<=rect.right&&y>=rect.top&&y<=rect.bottom;}
static std::wstring duration(double seconds){if(!std::isfinite(seconds)||seconds<0)seconds=0;unsigned total=unsigned(seconds);std::wostringstream value;if(total>=3600)value<<total/3600<<L":"<<std::setfill(L'0')<<std::setw(2)<<(total/60)%60;else value<<total/60;value<<L":"<<std::setfill(L'0')<<std::setw(2)<<total%60;return value.str();}
static std::wstring number(int value,int width=2){std::wostringstream text;text<<std::setfill(L'0')<<std::setw(width)<<value;return text.str();}
static json choices(std::initializer_list<std::pair<json,std::string>> values){json result=json::array();for(auto& value:values)result.push_back({{"value",value.first},{"label",value.second}});return result;}
static std::wstring label(const json& value){return wide(value.is_string()?value.get<std::string>():value.dump());}
static const json& arrayField(const json& object,const char* key){static const json empty=json::array();auto found=object.find(key);return found!=object.end()&&found->is_array()?*found:empty;}
