void Ui::sliderAt(const Hit& hit,float x){if(hit.disabled)return;double min=hit.args.value("min",0.),max=hit.args.value("max",1.),step=hit.args.value("step",.01),ratio=std::clamp(double((x-hit.rect.left)/(hit.rect.right-hit.rect.left)),0.,1.),value=std::clamp(std::round(std::lerp(min,max,ratio)/step)*step,min,max);auto args=hit.args;args["value"]=value;if(args.value("group",std::string(""))=="seek")seekPreview_=value;else emit_("set",args);}
