void Ui::wheel(float pixels){if(!model_||std::abs(pixels)<.001f)return;if(notificationVisible_&&notificationScrollMax_>0&&contains(notificationBounds_,pointerX_,pointerY_)){notificationScroll_=std::clamp(notificationScroll_+pixels/scale_,0.f,notificationScrollMax_);return;}if(model_->viewer){emit_("viewer-zoom",{{"pixels",pixels}});return;}focusVisible_=false;pixels/=scale_;if(dropdown_.open){dropdown_.selected=wrap(dropdown_.selected+(pixels>0?1:-1),int(dropdown_.source.args.at("values").size()));return;}if(!model_->panel.empty())scrollTo(ScrollArea::panel,scroll_+pixels);else if(model_->detail){scrollTo(ScrollArea::detail,detailScroll_+pixels);}else emit_("navigate",{{"row",pixels>0?1:-1}});}
bool Ui::editing()const{HWND focused=GetFocus();for(auto& [key,input]:inputs_)if(input.handle==focused)return true;return false;}
std::wstring Ui::field(const std::string& key)const{auto found=inputs_.find(key);if(found==inputs_.end()||!found->second.handle)return {};int length=GetWindowTextLengthW(found->second.handle);std::wstring result(size_t(length)+1,L'\0');GetWindowTextW(found->second.handle,result.data(),length+1);result.resize(length);return result;}
json Ui::fields()const{json result=json::object();for(auto& [key,input]:inputs_)result[key]=utf8(field(key));return result;}
